43	class XdsOverrideHostTest : public LoadBalancingPolicyTest {
44	 protected:
45	  XdsOverrideHostTest()
46	      : policy_(MakeLbPolicy("xds_override_host_experimental")) {}
47	
48	  RefCountedPtr<LoadBalancingPolicy::Config> MakeXdsOverrideHostConfig(
49	      std::string child_policy = "round_robin") {
50	    Json::Object child_policy_config = {{child_policy, Json::Object()}};
51	    return MakeConfig(Json::Array{Json::Object{
52	        {"xds_override_host_experimental",
53	         Json::Object{{"childPolicy", Json::Array{{child_policy_config}}}}}}});
54	  }
55	
56	  RefCountedPtr<LoadBalancingPolicy::SubchannelPicker>
57	  ExpectStartupWithRoundRobin(absl::Span<const absl::string_view> addresses) {
58	    RefCountedPtr<LoadBalancingPolicy::SubchannelPicker> picker;
59	    EXPECT_EQ(ApplyUpdate(BuildUpdate(addresses, MakeXdsOverrideHostConfig()),
60	                          policy_.get()),
61	              absl::OkStatus());
62	    ExpectConnectingUpdate();
63	    for (size_t i = 0; i < addresses.size(); ++i) {
64	      auto* subchannel = FindSubchannel(addresses[i]);
65	      EXPECT_NE(subchannel, nullptr);
66	      if (subchannel == nullptr) return nullptr;
67	      EXPECT_TRUE(subchannel->ConnectionRequested());
68	      subchannel->SetConnectivityState(GRPC_CHANNEL_CONNECTING);
69	      subchannel->SetConnectivityState(GRPC_CHANNEL_READY);
70	      if (i == 0) {
71	        picker = WaitForConnected();
72	        ExpectRoundRobinPicks(picker.get(), {addresses[0]});
73	      } else {
74	        picker = WaitForRoundRobinListChange(
75	            absl::MakeSpan(addresses).subspan(0, i),
76	            absl::MakeSpan(addresses).subspan(0, i + 1));
77	      }
78	    }
79	    return picker;
80	  }
81	
82	  OrphanablePtr<LoadBalancingPolicy> policy_;
83	};
