85	TEST_F(XdsOverrideHostTest, DelegatesToChild) {
86	  ExpectStartupWithRoundRobin(
87	      {"ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442", "ipv4:127.0.0.1:443"});
88	}
