163	      void Eject() {
164	        ejected_ = true;
165	        if (last_seen_state_.has_value()) {
166	          watcher_->OnConnectivityStateChange(
167	              GRPC_CHANNEL_TRANSIENT_FAILURE,
168	              absl::UnavailableError(
