XdsOverrideHostLb::Picker::PickOverridenHost(absl::string_view override_host) {
  GPR_ASSERT(!override_host.empty());
  auto subchannel = policy_->LookupSubchannel(override_host);
  if (subchannel == nullptr) {
    return absl::nullopt;
  }
  switch (subchannel->connectivity_state()) {
    case GRPC_CHANNEL_READY:
      // The subchannel is ready; route the pick to it.
      return PickResult::Complete(subchannel->wrapped_subchannel());
    case GRPC_CHANNEL_IDLE:
      // The subchannel is idle; ask it to connect and queue the pick until
      // the connection is established.
      subchannel->wrapped_subchannel()->RequestConnection();
      ABSL_FALLTHROUGH_INTENDED;
    case GRPC_CHANNEL_CONNECTING:
      // The subchannel is connecting; queue the pick until it is ready.
      return PickResult::Queue();
    default:
      // The subchannel is in TRANSIENT_FAILURE (or SHUTDOWN); don't honor
      // the override.  Fall through to the child picker so that we use one
      // of the remaining ready subchannels.
      return absl::nullopt;
  }
}

