void XdsOverrideHostLb::SubchannelWrapper::WatchConnectivityState(
    std::unique_ptr<ConnectivityStateWatcherInterface> watcher) {
  auto watcher_wrapper =
      std::make_unique<WatcherWrapper>(std::move(watcher), Ref());
  watcher_map_[watcher.get()] = watcher_wrapper.get();
  wrapped_subchannel()->WatchConnectivityState(std::move(watcher_wrapper));
}

void XdsOverrideHostLb::SubchannelWrapper::CancelConnectivityStateWatch(
    ConnectivityStateWatcherInterface* watcher) {
  auto it = watcher_map_.find(watcher);
  if (it == watcher_map_.end()) return;
  wrapped_subchannel()->CancelConnectivityStateWatch(it->second);
  watcher_map_.erase(it);
}

void XdsOverrideHostLb::SubchannelWrapper::UpdateConnectivityState(
    grpc_connectivity_state state) {
  // For a tracked override host, request re-resolution when the subchannel
  // transitions to IDLE or TRANSIENT_FAILURE, so that the control plane has
  // a chance to give us a usable host again.  We only do this on an actual
  // transition, not on the initial state report.
  const bool report_reresolution =
      key_.has_value() && last_seen_state_.has_value() &&
      (state == GRPC_CHANNEL_IDLE ||
       state == GRPC_CHANNEL_TRANSIENT_FAILURE);
  last_seen_state_ = state;
  connectivity_state_.store(state, std::memory_order_relaxed);
  if (report_reresolution) {
    policy_->RequestReresolutionForSubchannel();
  }
