292	absl::optional<LoadBalancingPolicy::PickResult>
293	XdsOverrideHostLb::Picker::PickOverridenHost(absl::string_view override_host) {
294	  GPR_ASSERT(!override_host.empty());
295	  auto subchannel = policy_->LookupSubchannel(override_host);
296	  if (subchannel == nullptr) {
297	    return absl::nullopt;
298	  }
299	  switch (subchannel->connectivity_state()) {
300	    case GRPC_CHANNEL_READY:
301	      // The subchannel is ready; route the pick to it.
302	      return PickResult::Complete(subchannel->wrapped_subchannel());
303	    case GRPC_CHANNEL_IDLE:
304	      // The subchannel is idle; ask it to connect and queue the pick until
305	      // the connection is established.
306	      subchannel->wrapped_subchannel()->RequestConnection();
307	      return PickResult::Queue();
308	    case GRPC_CHANNEL_CONNECTING:
309	      // The subchannel is connecting; queue the pick until it is ready.
310	      return PickResult::Queue();
311	    default:
312	      // The subchannel is in TRANSIENT_FAILURE (or SHUTDOWN); don't honor
313	      // the override.  Fall through to the child picker so that we use one
314	      // of the remaining ready subchannels.
315	      return absl::nullopt;
316	  }
317	}
