319	LoadBalancingPolicy::PickResult XdsOverrideHostLb::Picker::Pick(
320	    LoadBalancingPolicy::PickArgs args) {
321	  auto* call_state = static_cast<LbCallStateInternal*>(args.call_state);
322	  auto override_host = call_state->GetCallAttribute(XdsHostOverrideTypeName());
323	  if (!override_host.empty()) {
324	    auto overridden_host_pick = PickOverridenHost(override_host);
325	    if (overridden_host_pick.has_value()) {
326	      return std::move(*overridden_host_pick);
327	    }
328	  }
329	  // No usable override.  Delegate to the child picker.
330	  if (picker_ == nullptr) {  // Should never happen.
331	    return PickResult::Fail(absl::InternalError(
332	        "xds_override_host picker not given any child picker"));
333	  }
334	  auto result = picker_->Pick(args);
335	  auto complete_pick = absl::get_if<PickResult::Complete>(&result.result);
336	  if (complete_pick != nullptr) {
337	    complete_pick->subchannel =
338	        static_cast<SubchannelWrapper*>(complete_pick->subchannel.get())
339	            ->wrapped_subchannel();
340	  }

